(* [comment removed for export] *)
Lemma rl8_Hf : forall regs m (DW : Z), (32 <= DW < 2 ^ 31)%Z ->
  getr regs 6 = Z_to_bv 64 DW -> getr regs 29 = Z_to_bv 64 32 ->
  exists regs', msteps SEGS (mkst regs (0x7ab78 : word) m rom) (mkst regs' (0x7ab80 : word) m rom)
