(* [comment removed for export] *)
Lemma rl8_S : forall regs m (DW i swpl dwpl psf pdf k : Z),
  (1 <= DW < 32)%Z -> (1 <= k < 32)%Z -> (0 <= i < 2 ^ 24)%Z -> (0 <= swpl < 2 ^ 24)%Z -> (0 <= dwpl < 2 ^ 24)%Z ->
  getr regs 6 = Z_to_bv 64 DW -> getr regs 29 = Z_to_bv 64 32 -> getr regs 10 = Z_to_bv 64 i -> getr regs 13 = Z_to_bv 64 swpl ->
  getr regs 14 = Z_to_bv 64 dwpl -> getr regs 16 = Z_to_bv 64 psf -> getr regs 17 = Z_to_bv 64 pdf -> getr regs 15 = Z_to_bv 64 k ->
  exists regs',
    msteps SEGS (mkst regs (0x7ab78 : word) m rom) (mkst regs' (0x7ab50 : word) m rom)
    /\ getr regs' 8 = Z_to_bv 64 (pdf + 4 * (i * dwpl)) /\ getr regs' 9 = Z_to_bv 64 (psf + 4 * (i * swpl))
    /\ regs_agree (fun r => In r [8; 9; 18]%list) regs regs'.
